mapper.select:
SELECT o.*, r.error_message, (SELECT COUNT(*) FROM run_attempt a WHERE a.enterprise_id = o.enterprise_id AND a.run_id = o.run_id) AS attempt_count FROM scheduled_occurrence o LEFT JOIN agent_run r ON r.enterprise_id = o.enterprise_id AND r.id = o.run_id WHERE o.enterprise_id = #{enterprise} AND o.schedule_id = #{schedule}
AND (o.scheduled_for < #{cursor.time} OR (o.scheduled_for = #{cursor.time} AND o.id < #{cursor.id}))
ORDER BY o.scheduled_for DESC, o.id DESC LIMIT #{limit}
